  insert into public.questions (id, owner_id, set_id, type, stem, options, correct, explanation, difficulty, status, position, created_at) values
    ('50a63d83-3d35-49c1-af7d-6f72589d9921', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Vedic Period is generally dated to which time bracket?', '["2500 BC - 1500 BC", "1500 BC - 600 BC", "1000 BC - 300 BC", "600 BC - 200 BC"]'::jsonb, '"1500 BC - 600 BC"'::jsonb, NULL, 'medium', 'active', 0, '2026-08-02 19:15:10.751603+00'),
    ('2081bc5a-f22d-4bbe-80a5-c8a1f00ac1c1', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Vedic Period is divided into two phases. What is the time bracket of the Early Vedic (Rigvedic) Period?', '["1500 BC - 1000 BC", "1000 BC - 600 BC", "2000 BC - 1500 BC", "1500 BC - 600 BC"]'::jsonb, '"1500 BC - 1000 BC"'::jsonb, NULL, 'medium', 'active', 1, '2026-08-02 19:15:10.751603+00'),
    ('2816a71b-e57d-423f-8cce-26627a9fabae', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Later Vedic Period is dated to which time bracket?', '["1500 BC - 1000 BC", "1000 BC - 600 BC", "2000 BC - 1500 BC", "600 BC - 300 BC"]'::jsonb, '"1000 BC - 600 BC"'::jsonb, NULL, 'medium', 'active', 2, '2026-08-02 19:15:10.751603+00'),
    ('463583c3-9787-4743-a509-8b2187673a82', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The literal meaning of the word ''Veda'' is:', '["Fire", "Knowledge", "Sacrifice", "Hymn"]'::jsonb, '"Knowledge"'::jsonb, NULL, 'medium', 'active', 3, '2026-08-02 19:15:10.751603+00'),
    ('c45f1b4e-2a7c-4c78-bebf-977cf46cb840', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Vedic Civilization is also known as the ''Aryan Civilization'' because:', '["It was discovered by Aryan archaeologists", "Aryans were the creators of this civilization", "It began in Aryavarta", "The Vedas were written by Aryans only"]'::jsonb, '"Aryans were the creators of this civilization"'::jsonb, NULL, 'medium', 'active', 4, '2026-08-02 19:15:10.751603+00'),
    ('8fb56a27-1615-4c33-b56f-0a0e854475fa', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The term ''Aryan'' is related to which language family, and literally means ''Best/Great''?', '["Dravidian language family", "Indo-European language family", "Austric language family", "Sino-Tibetan language family"]'::jsonb, '"Indo-European language family"'::jsonb, NULL, 'medium', 'active', 5, '2026-08-02 19:15:10.751603+00'),
    ('3b77f601-77b4-473b-8747-9ca901f8c056', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The primary source for reconstructing the history of the Vedic Period is:', '["Epigraphic (inscriptional) evidence alone", "Vedic Literature (text-based sources)", "Numismatic evidence", "Foreign travellers'' accounts"]'::jsonb, '"Vedic Literature (text-based sources)"'::jsonb, 'The notes flag this as an important point - the Vedic Period''s source is primarily literature/text-based, unlike the IVC''s archaeological sources.', 'medium', 'active', 6, '2026-08-02 19:15:10.751603+00'),
    ('637f718a-88a4-4819-8dc2-5f143809ff20', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Boghazkoi inscription, an important archaeological source mentioning Vedic gods, was found in:', '["Mesopotamia", "Asia Minor (Turkey)", "Iraq-Syria", "Egypt"]'::jsonb, '"Asia Minor (Turkey)"'::jsonb, NULL, 'medium', 'active', 7, '2026-08-02 19:15:10.751603+00'),
    ('7f0f3c8a-a172-409b-9e08-d36f61ed754b', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Boghazkoi inscription is dated to approximately:', '["1400 BC", "1600 BC", "1200 BC", "1000 BC"]'::jsonb, '"1400 BC"'::jsonb, NULL, 'medium', 'active', 8, '2026-08-02 19:15:10.751603+00'),
    ('6166f44e-91a6-4a38-ae2a-35882a1be4e5', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'How many Vedic gods are mentioned in the Boghazkoi inscription?', '["Two", "Three", "Four", "Five"]'::jsonb, '"Four"'::jsonb, 'Indra, Mitra, Varuna, and Nastya (Nasatya) are mentioned.', 'medium', 'active', 9, '2026-08-02 19:15:10.751603+00'),
    ('ee332298-377d-49e4-a9ae-453366accd72', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which of the following is NOT one of the four Vedic gods mentioned in the Boghazkoi inscription?', '["Indra", "Mitra", "Varuna", "Agni"]'::jsonb, '"Agni"'::jsonb, 'The four gods mentioned are Indra, Mitra, Varuna, and Nastya (Nasatya).', 'medium', 'active', 10, '2026-08-02 19:15:10.751603+00'),
    ('7a69066b-36fc-4bfb-a9b1-10c96d972d34', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Kassi/Kassite inscription, which mentions two Vedic gods (Suryash and Marutash), was found in:', '["Asia Minor (Turkey)", "Mesopotamia", "Iraq-Syria", "Iran"]'::jsonb, '"Mesopotamia"'::jsonb, NULL, 'medium', 'active', 11, '2026-08-02 19:15:10.751603+00'),
    ('a589519e-67cb-42ab-8320-6694c62620f8', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Kassite inscription is dated to approximately:', '["1400 BC", "1600 BC", "1200 BC", "1800 BC"]'::jsonb, '"1600 BC"'::jsonb, NULL, 'medium', 'active', 12, '2026-08-02 19:15:10.751603+00'),
    ('d696075b-6d40-4495-8db7-ebc9844c93be', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which two Vedic gods are mentioned in the Kassite inscription?', '["Indra and Varuna", "Suryash and Marutash", "Mitra and Nastya", "Agni and Soma"]'::jsonb, '"Suryash and Marutash"'::jsonb, 'Suryash corresponds to Surya (Sun god) and Marutash corresponds to Marut.', 'medium', 'active', 13, '2026-08-02 19:15:10.751603+00'),
    ('1866999f-1fc3-49f7-bb5d-19e1173cfef3', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Mitanni inscription, dated to around 1400 BC, was found in which region?', '["Asia Minor (Turkey)", "Mesopotamia", "Iraq-Syria", "Egypt"]'::jsonb, '"Iraq-Syria"'::jsonb, NULL, 'medium', 'active', 14, '2026-08-02 19:15:10.751603+00'),
    ('d60e4de6-3be5-4595-9724-9990320f1530', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Mitanni inscription suggests that a branch of Aryans migrated towards Iraq from:', '["India", "Iran", "Central Asia", "Turkey"]'::jsonb, '"Iran"'::jsonb, NULL, 'medium', 'active', 15, '2026-08-02 19:15:10.751603+00'),
    ('dcfb98f8-c7af-461b-bc5f-c3d07cab969e', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which pottery type is associated with the Rigvedic (Early Vedic) Period and is also known as Ochre-Coloured Ware?', '["OCW", "PGW", "NBPW", "BRW"]'::jsonb, '"OCW"'::jsonb, NULL, 'medium', 'active', 16, '2026-08-02 19:15:10.751603+00'),
    ('94adc860-f634-46a5-91a0-c596a1f94caa', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'What does ''OCW,'' the pottery associated with the Rigvedic Period, stand for?', '["Ochre-Coloured Ware", "Overglazed Ceramic Ware", "Orange Clay Ware", "Old Coarse Ware"]'::jsonb, '"Ochre-Coloured Ware"'::jsonb, NULL, 'medium', 'active', 17, '2026-08-02 19:15:10.751603+00'),
    ('31af7087-2051-44c7-8b6b-99bf561bb712', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'BRW, another pottery type of the Rigvedic Period, refers to:', '["Black and Red Ware", "Buff Red Ware", "Bright Red Ware", "Brown Ring Ware"]'::jsonb, '"Black and Red Ware"'::jsonb, NULL, 'medium', 'active', 18, '2026-08-02 19:15:10.751603+00'),
    ('c9b8b8e5-5b6f-42c6-9344-1e0d9f7efc4c', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The pottery of the Later Vedic Period is related to which technological age?', '["Stone Age", "Bronze Age", "Iron Age", "Chalcolithic Age"]'::jsonb, '"Iron Age"'::jsonb, NULL, 'medium', 'active', 19, '2026-08-02 19:15:10.751603+00'),
    ('79e80778-9aa4-487d-8779-2bdfcdd9a1f3', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The initial pottery phase of the Later Vedic Period is represented by:', '["OCW", "PGW (Painted Grey Ware)", "BRW", "NBPW"]'::jsonb, '"PGW (Painted Grey Ware)"'::jsonb, NULL, 'medium', 'active', 20, '2026-08-02 19:15:10.751603+00'),
    ('0883753a-3b7b-4223-aa14-5b9fb6a926f9', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'What does PGW, the pottery of the initial phase of the Later Vedic Period, stand for?', '["Painted Grey Ware", "Polished Glazed Ware", "Plain Grey Ware", "Pre-Grey Ware"]'::jsonb, '"Painted Grey Ware"'::jsonb, NULL, 'medium', 'active', 21, '2026-08-02 19:15:10.751603+00'),
    ('dc09f27f-bf8e-439b-b8ee-4e609519828b', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'NBPW, the pottery of the last phase of the Later Vedic Period and considered the most advanced pottery, stands for:', '["Northern Black Polished Ware", "New Bronze Painted Ware", "Northern Buff Painted Ware", "Native Black Plain Ware"]'::jsonb, '"Northern Black Polished Ware"'::jsonb, NULL, 'medium', 'active', 22, '2026-08-02 19:15:10.751603+00'),
    ('db54baf1-48cf-448e-96a3-00cf53f24244', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which pottery type is considered the most advanced pottery of the Vedic Period and is associated with the Iron Age?', '["OCW", "BRW", "PGW", "NBPW"]'::jsonb, '"NBPW"'::jsonb, NULL, 'medium', 'active', 23, '2026-08-02 19:15:10.751603+00'),
    ('7465bf2e-e9db-49b1-92a1-3f420321a819', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Match the following pottery types with their correct full forms is a common BPSC-style question. NBPW is associated with which phase?', '["Initial phase of Later Vedic Period", "Last phase of Later Vedic Period", "Early Rigvedic Period", "Pre-Vedic Period"]'::jsonb, '"Last phase of Later Vedic Period"'::jsonb, NULL, 'medium', 'active', 24, '2026-08-02 19:15:10.751603+00'),
    ('7134eaa1-b357-4520-a269-a2a0c275bb4e', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', '''Copper Hoard'' culture, mentioned alongside Vedic pottery traditions in the notes, is generally associated with:', '["The Rigvedic and Later Vedic transitional phases", "Only the Mauryan period", "Only the Gupta period", "The Indus Valley Civilization exclusively"]'::jsonb, '"The Rigvedic and Later Vedic transitional phases"'::jsonb, NULL, 'medium', 'active', 25, '2026-08-02 19:15:10.751603+00'),
    ('d68c8124-fd49-4253-a29b-6b07fbe735b8', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Zend Avesta, considered a ''sister source'' to Rigvedic period literature, is the sacred text of which ancient religion/region?', '["Persian (Zoroastrian) text", "Egyptian text", "Mesopotamian text", "Chinese text"]'::jsonb, '"Persian (Zoroastrian) text"'::jsonb, NULL, 'medium', 'active', 26, '2026-08-02 19:15:10.751603+00'),
    ('721c378e-2514-499f-9829-7026a8a4c62d', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Zend Avesta is dated to approximately which century BC?', '["10th century BC", "14th century BC", "8th century BC", "6th century BC"]'::jsonb, '"14th century BC"'::jsonb, NULL, 'medium', 'active', 27, '2026-08-02 19:15:10.751603+00'),
    ('0c05f555-7fcb-4760-82a9-95081e33b500', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Vedic Literature is broadly divided into two categories:', '["Shruti and Smriti Literature", "Vedic and Upavedic Literature", "Samhita and Sutra Literature", "Purana and Itihasa Literature"]'::jsonb, '"Shruti and Smriti Literature"'::jsonb, NULL, 'medium', 'active', 28, '2026-08-02 19:15:10.751603+00'),
    ('1ea48a55-4978-4c30-b528-fb8e7a43ba22', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which of the following is NOT part of Shruti Literature?', '["Veda", "Brahmana", "Purana", "Aranyaka"]'::jsonb, '"Purana"'::jsonb, 'Shruti Literature = Veda, Brahmana, Aranyaka, Upanishad. Purana belongs to Smriti Literature.', 'medium', 'active', 29, '2026-08-02 19:15:10.751603+00'),
    ('93366184-367e-4321-bef1-0cff19e72d52', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The four components of Shruti Literature, in order, are:', '["Veda, Brahmana, Aranyaka, Upanishad", "Veda, Purana, Sutra, Upanishad", "Veda, Smriti, Aranyaka, Epics", "Brahmana, Veda, Upanishad, Purana"]'::jsonb, '"Veda, Brahmana, Aranyaka, Upanishad"'::jsonb, NULL, 'medium', 'active', 30, '2026-08-02 19:15:10.751603+00'),
    ('9e5704d4-b2ab-4254-8eab-627e0918321c', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which text of Shruti Literature is also known as ''Vedanta''?', '["Brahmana", "Aranyaka", "Upanishad", "Veda"]'::jsonb, '"Upanishad"'::jsonb, NULL, 'medium', 'active', 31, '2026-08-02 19:15:10.751603+00'),
    ('11c90c9a-02b3-4db6-b370-8e3c5d532878', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which of the following belongs to Smriti Literature, NOT Shruti Literature?', '["Upanishad", "Brahmana", "Vedanga", "Veda"]'::jsonb, '"Vedanga"'::jsonb, 'Smriti Literature includes Vedanga, Purana, Shad Darshana, Upaveda, Sutra Literature, and Epics.', 'medium', 'active', 32, '2026-08-02 19:15:10.751603+00'),
    ('2567e8db-b846-4c98-83b5-1ec1abb61c31', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which of the following is included under Smriti Literature?', '["Aranyaka", "Veda", "Puranas and Epics", "Upanishad"]'::jsonb, '"Puranas and Epics"'::jsonb, NULL, 'medium', 'active', 33, '2026-08-02 19:15:10.751603+00'),
    ('11847897-55b6-4a02-8aeb-ea4109f8facf', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Shad Darshana (the six schools of Indian philosophy) is classified under which category of Vedic literature?', '["Shruti Literature", "Smriti Literature", "Neither Shruti nor Smriti", "Both equally"]'::jsonb, '"Smriti Literature"'::jsonb, NULL, 'medium', 'active', 34, '2026-08-02 19:15:10.751603+00'),
    ('c1c49e4a-0561-4fc6-803d-ce5deb2beacd', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'Which of these is an example of Upaveda, classified under Smriti Literature?', '["Rigveda", "Ayurveda", "Upanishad", "Aranyaka"]'::jsonb, '"Ayurveda"'::jsonb, 'Upaveda refers to auxiliary/applied fields of knowledge such as Ayurveda, Dhanurveda, etc.', 'medium', 'active', 35, '2026-08-02 19:15:10.751603+00'),
    ('c05c3f52-3bea-4906-8ad2-2b9850a0cdcf', admin_id, '41dc1c0f-ac03-48e2-96e4-5aab9e150863', 'mcq', 'The Epics (Ramayana and Mahabharata) are classified under which category of Vedic-era literature?', '["Shruti Literature", "Smriti Literature", "Archaeological sources", "Foreign accounts"]'::jsonb, '"Smriti Literature"'::jsonb, NULL, 'medium', 'active', 36, '2026-08-02 19:15:10.751603+00'),
    ('eb78c38b-4999-4396-8a87-f145eca95b52', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'Where has the first evidence of rice (paddy) cultivation been found in the Indus Valley Civilization?', '["Kalibangan", "Lothal", "Banawali", "Rangpur"]'::jsonb, '"Lothal"'::jsonb, 'Rangpur also shows rice husk evidence, but Lothal is credited with the first evidence of rice.', 'medium', 'active', 0, '2026-08-02 19:19:39.950958+00'),
    ('ea5e5349-0c13-497c-803a-16d66d8a4533', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'The evidence of a ploughed field surface has been found at:', '["Kalibangan", "Banawali", "Lothal", "Kot Diji"]'::jsonb, '"Kalibangan"'::jsonb, NULL, 'medium', 'active', 1, '2026-08-02 19:19:39.950958+00'),
    ('ed4595fb-cdb9-469b-87f2-fa2566a1f70b', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'The Greeks referred to Indian cotton by which name, derived from the Sindhi language?', '["Karpasa", "Sindon", "Kappas", "Meluha"]'::jsonb, '"Sindon"'::jsonb, NULL, 'medium', 'active', 2, '2026-08-02 19:19:39.950958+00'),
    ('40c166d1-7709-41c4-9f47-9075e53d0931', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'The largest granary of the Indus Valley Civilization, with 27 compartments and situated on a high brick platform, has been found at:', '["Harappa", "Kalibangan", "Mohenjo-daro", "Dholavira"]'::jsonb, '"Mohenjo-daro"'::jsonb, NULL, 'medium', 'active', 3, '2026-08-02 19:19:39.950958+00'),
    ('890d0de9-0238-4d18-b96f-e86dc56175fe', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'Evidence of a Terracotta Plough has been found at:', '["Kalibangan", "Banwali", "Lothal", "Rangpur"]'::jsonb, '"Banwali"'::jsonb, NULL, 'medium', 'active', 4, '2026-08-02 19:19:39.950958+00'),
    ('3d0f3b46-776f-4af4-9927-9cd665fdb8e9', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'Which animal''s figure has NOT been found depicted on any IVC seal, despite the civilization''s clearly agrarian/pastoral economy?', '["Tiger", "Elephant", "Cow", "Buffalo"]'::jsonb, '"Cow"'::jsonb, 'This is flagged as a ''most important line'' in the notes.', 'medium', 'active', 5, '2026-08-02 19:19:39.950958+00'),
    ('15d603ec-2fb7-4492-8376-fee6c716e899', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'Which animal is notably absent from IVC seals despite the presence of tigers, elephants, and buffaloes?', '["Rhinoceros", "Lion", "Bull", "Unicorn"]'::jsonb, '"Lion"'::jsonb, NULL, 'medium', 'active', 6, '2026-08-02 19:19:39.950958+00'),
    ('99a32f36-256b-4e68-9a74-c4c811f44e61', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'Skeletal remains of a horse from the early Harappan level have been reported from:', '["Surkotada (Gujarat)", "Rana Ghundai (Pakistan)", "Lothal (Gujarat)", "Kalibangan (Rajasthan)"]'::jsonb, '"Rana Ghundai (Pakistan)"'::jsonb, 'Horse bone remains (late Harappan) come from Surkotada; terracotta horse figurines from Lothal and Kalibangan.', 'medium', 'active', 7, '2026-08-02 19:19:39.950958+00'),
    ('833bdb6e-3999-4fd9-a00b-917dc8593f70', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'Sumerian texts mention Indus Valley traders coming from a land called:', '["Dilmun", "Meluha", "Magan", "Elam"]'::jsonb, '"Meluha"'::jsonb, NULL, 'medium', 'active', 8, '2026-08-02 19:19:39.950958+00'),
    ('ba76e6a9-4c6c-463b-ac0e-64f8782547d9', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'According to Mesopotamian texts, which of the following was NOT among the products imported from Meluha (the Indus region)?', '["Carnelian", "Lapis lazuli", "Tin", "Copper"]'::jsonb, '"Tin"'::jsonb, 'Carnelian, copper, gold, and wood were Meluha exports; tin was itself imported into the Indus region from Iran/Afghanistan.', 'medium', 'active', 9, '2026-08-02 19:19:39.950958+00'),
