    ('8ff2fdbc-2994-4784-89ef-b8f5b1671a80', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'Who proposed the ''Aryan invasion'' theory to explain the sudden decline of the Harappan civilization?', '["John Marshall", "Mortimer Wheeler", "Gordon Childe", "R.D. Banerjee"]'::jsonb, '"Mortimer Wheeler"'::jsonb, NULL, 'medium', 'active', 63, '2026-08-02 19:19:39.950958+00'),
