    ('9bf8da31-a36b-4eda-8a1e-f35610af7cce', admin_id, '744077f3-09b7-409f-8100-d2b2efa865e9', 'mcq', 'The theory that floods caused the decline of Mohenjo-daro was proposed by:', '["M.R. Sahni", "John Marshall and J.H. Mackay", "Gurdeep Singh", "Mortimer Wheeler"]'::jsonb, '"John Marshall and J.H. Mackay"'::jsonb, NULL, 'medium', 'active', 65, '2026-08-02 19:19:39.950958+00'),
