    ('322a645d-9f66-47ca-9c8c-f0df09e165d0', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Which Harappan site is located in Maharashtra?', '["Daimabad", "Manda", "Kalibanga", "Hulas"]'::jsonb, '"Daimabad"'::jsonb, NULL, 'medium', 'active', 24, '2026-08-02 20:16:58.292127+00'),
