    ('c5950273-7839-4a34-8afb-3a6d29c2c796', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Regarding the creators of the Indus Valley Civilization, there are two popular views. What are they called?', '["Foreign Origin Theory and Indigenous Origin Theory", "Aryan Theory and Dravidian Theory", "Vedic Theory and Harappan Theory", "Migration Theory and Invasion Theory"]'::jsonb, '"Foreign Origin Theory and Indigenous Origin Theory"'::jsonb, NULL, 'medium', 'active', 27, '2026-08-02 20:16:58.292127+00'),
    ('1ec17ed1-f389-4408-9070-dc407dd9b8c1', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'The Foreign Origin Theory holds that the Indus Valley Civilization was created by the people of which civilization?', '["Egyptian Civilization", "Chinese Civilization", "Mesopotamian Civilization", "Greek Civilization"]'::jsonb, '"Mesopotamian Civilization"'::jsonb, NULL, 'medium', 'active', 28, '2026-08-02 20:16:58.292127+00'),
    ('e3dd964b-56fa-43a4-9000-04f9e8c66a69', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Which of the following scholars supported the Foreign Origin Theory of the IVC?', '["Gordon Childe, John Marshall, Mortimer Wheeler, D.D. Kosambi", "Suniti Chatterjee, S.R. Rao", "Amalanand Ghosh, D.P. Agarwal", "Romila Thapar, Fair Servis"]'::jsonb, '"Gordon Childe, John Marshall, Mortimer Wheeler, D.D. Kosambi"'::jsonb, NULL, 'medium', 'active', 29, '2026-08-02 20:16:58.292127+00'),
    ('f6ad499e-f7af-41f9-8160-8d45b322e89b', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Which theory of IVC origin is considered the ''most appropriate'' as per the notes?', '["Foreign Origin Theory", "Indigenous Origin Theory", "Aryan Invasion Theory", "Neither theory is accepted"]'::jsonb, '"Indigenous Origin Theory"'::jsonb, NULL, 'medium', 'active', 30, '2026-08-02 20:16:58.292127+00'),
    ('52722531-9d6d-4daa-8202-744818bda7ad', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Suniti Chatterjee argued that the Indus Valley Civilization originated from which cultural source?', '["Aryan Culture", "Dravidian Culture", "Sothi Culture", "Iran-Baloch Rural Farmer Culture"]'::jsonb, '"Dravidian Culture"'::jsonb, NULL, 'medium', 'active', 31, '2026-08-02 20:16:58.292127+00'),
    ('5589782a-2592-49f0-a35e-619be49f7ba6', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Which of the following scholars argued that the IVC originated from Aryan Culture — a view the notes state ''cannot be accepted''?', '["Laxman Swaroop Pulaskar, T. Ramachandran, S.R. Rao, K.N. Shastri", "Suniti Chatterjee", "Amalanand Ghosh, D.P. Agarwal", "Romila Thapar, Fair Servis"]'::jsonb, '"Laxman Swaroop Pulaskar, T. Ramachandran, S.R. Rao, K.N. Shastri"'::jsonb, NULL, 'medium', 'active', 32, '2026-08-02 20:16:58.292127+00'),
    ('049003df-eae2-412f-8c49-c548430fb9db', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Amalanand Ghosh and D.P. Agarwal linked the origin of the Indus Valley Civilization to which rural culture?', '["Sothi Culture", "Dravidian Culture", "Iran-Baloch Culture", "Aryan Culture"]'::jsonb, '"Sothi Culture"'::jsonb, NULL, 'medium', 'active', 33, '2026-08-02 20:16:58.292127+00'),
