    ('472bf151-4fc3-4d1d-8a41-d7ef2baef9a3', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'match', 'Match the scholar(s) with the cultural-origin theory they proposed for the IVC (Indigenous Origin Theory sub-views).', '{"left": ["Suniti Chatterjee", "Amalanand Ghosh and D.P. Agarwal", "Romila Thapar and Fair Servis", "Laxman Swaroop Pulaskar, T. Ramachandran, S.R. Rao, K.N. Shastri"], "right": ["Iran-Baloch Rural Farmer Culture", "Sothi Culture (Rural Culture)", "Aryan Culture (view not accepted)", "Dravidian Culture"]}'::jsonb, '["Dravidian Culture", "Sothi Culture (Rural Culture)", "Iran-Baloch Rural Farmer Culture", "Aryan Culture (view not accepted)"]'::jsonb, NULL, 'medium', 'active', 35, '2026-08-02 20:16:58.292127+00'),
    ('5e5a7d28-3888-428e-850a-03353b4676d8', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'The population of the Indus Valley Civilization is generally described as:', '["Homogeneous (single race)", "Heterogeneous / Mixed race (multi-ethnic population)", "Purely Mongoloid", "Purely Proto-Australoid"]'::jsonb, '"Heterogeneous / Mixed race (multi-ethnic population)"'::jsonb, NULL, 'medium', 'active', 36, '2026-08-02 20:16:58.292127+00'),
    ('090514ab-6f5c-463c-87c3-0ddf9221f8f8', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Which of the following was NOT one of the four races identified in the Indus Valley Civilization population?', '["Proto-Australoid", "Mediterranean", "Alpine", "Negroid"]'::jsonb, '"Negroid"'::jsonb, 'The four races were Proto-Australoid, Mediterranean, Alpine, and Mongoloid.', 'medium', 'active', 37, '2026-08-02 20:16:58.292127+00'),
    ('4499d63b-cb91-40c6-89ed-ff5235f585c4', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Which race formed the MAJORITY of the population in the Indus Valley Civilization?', '["Proto-Australoid", "Mediterranean", "Alpine", "Mongoloid"]'::jsonb, '"Mediterranean"'::jsonb, NULL, 'medium', 'active', 38, '2026-08-02 20:16:58.292127+00'),
    ('9b0cdbe7-8038-4cfa-bfaa-2fb85d620008', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'DNA extracted from Harappan skeletal remains for reconstructing ancient population genetics was obtained from which site?', '["Mohenjo-daro", "Harappa", "Rakhigarhi", "Lothal"]'::jsonb, '"Rakhigarhi"'::jsonb, NULL, 'medium', 'active', 39, '2026-08-02 20:16:58.292127+00'),
    ('aae8ff0e-e01c-4276-84b2-92a0f96b3142', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Which of the following pairs (Harappan site – region) is INCORRECTLY matched?', '["Mundigak – Afghanistan", "Kotdiji – Sindh, Pakistan", "Rojdi – Kathiawar, Gujarat", "Kunal – East Punjab, India"]'::jsonb, '"Kunal – East Punjab, India"'::jsonb, 'Kunal is located in Haryana, not East Punjab.', 'medium', 'active', 40, '2026-08-02 20:16:58.292127+00'),
    ('1bb5c057-f306-4512-9067-1288350d11ef', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Consider the following statements: (1) The northernmost Harappan site, Manda, is located on the Chenab river in Jammu. (2) The westernmost Harappan site, Sutkagen Dor, is located in Balochistan, Pakistan. (3) The IVC''s north-south extension (1400 km) was greater than its west-east extension (1600 km). Which of the statements is/are correct?', '["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 only"]'::jsonb, '"1 and 2 only"'::jsonb, 'Statement 3 is incorrect - the west-east extension (1600 km) was greater than the north-south extension (1400 km).', 'medium', 'active', 41, '2026-08-02 20:16:58.292127+00'),
    ('dbc2466e-4d3b-475a-aee5-e955ca67e912', admin_id, '07fe06ab-c861-41eb-b8e4-9cf71868793e', 'mcq', 'Which scholar(s) proposed the Foreign Origin Theory, holding that the IVC was created by people from the Mesopotamian Civilization?', '["Suniti Chatterjee", "Gordon Childe and John Marshall", "Amalanand Ghosh", "Romila Thapar"]'::jsonb, '"Gordon Childe and John Marshall"'::jsonb, NULL, 'medium', 'active', 42, '2026-08-02 20:16:58.292127+00')
