-- adityaissc7@gmail.com exists (sign up once on the deployed app).
-- Safe to re-run: existing rows with the same ids are skipped.

do $seed$
declare
  admin_id uuid;
begin
  select id into admin_id from public.profiles where lower(email) = 'adityaissc7@gmail.com';
  if admin_id is null then
    raise exception 'Sign up on the deployed app with adityaissc7@gmail.com first, then run this seed.';
  end if;

  on conflict (id) do nothing;

  on conflict (id) do nothing;

  on conflict (id) do nothing;
end
$seed$;
